// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

// Chúng ta sẽ dùng Ownable để quản lý các hàm của Hệ thống/Oracle
import { Ownable } from "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title EmergencyRescue
 * @dev Quản lý hồ sơ y tế và quy trình thưởng cứu hộ khẩn cấp.
 */
contract EmergencyRescue is Ownable {

    // =============================================================
    // STRUCTS (Cấu trúc Dữ liệu)
    // =============================================================

    /**
     * @dev Thông tin hồ sơ y tế cá nhân
     * @param name Tên (nên mã hóa)
     * @param age Tuổi
     * @param allergies Dị ứng
     * @param conditions Bệnh lý nền
     * @param isRegistered Trạng thái đăng ký
     */
    struct Profile {
        string name;
        uint256 age;
        string allergies;
        string conditions;
        bool isRegistered;
    }

    /**
     * @dev Lịch sử điều trị
     * @param timestamp Thời gian ghi nhận
     * @param location Nơi điều trị
     * @param verifierName Tên người xác nhận (Bác sĩ)
     * @param details Chi tiết (Thuốc, Tình trạng, Thiết bị...)
     */
    struct TreatmentLog {
        uint256 timestamp;
        string location;
        string verifierName;
        string details; // Gộp (Tình trạng, Thuốc, Thiết bị) cho đơn giản
    }

    /**
     * @dev Sự kiện khẩn cấp
     * @param patientAddress Địa chỉ ví của nạn nhân
     * @param patientCccd CCCD của nạn nhân (để liên kết hồ sơ)
     * @param rewardAmount Số tiền thưởng
     * @param potentialRescuers Danh sách người cứu hộ tiềm năng (đã được assign)
     * @param officialRescuerAddress Người cứu hộ chính thức (được nạn nhân confirm)
     * @param status Trạng thái: 0=Pending, 1=Assigned, 2=Confirmed, 3=Paid
     */
    struct EmergencyEvent {
        address patientAddress;
        string patientCccd;
        uint256 rewardAmount;
        address[] potentialRescuers;
        address officialRescuerAddress;
        uint8 status;
    }

    // =============================================================
    // STATE VARIABLES & MAPPINGS (Biến Trạng thái & Ánh xạ)
    // =============================================================

    // Dùng CCCD làm khóa chính (Key) cho hồ sơ
    mapping(string => Profile) public profiles;
    mapping(string => TreatmentLog[]) public treatmentLogs;

    // Dùng Event ID làm khóa chính
    mapping(uint256 => EmergencyEvent) public emergencyEvents;

    // Bộ đếm tự động cho Event ID
    uint256 public nextEventId;

    // =============================================================
    // EVENTS (Sự kiện)
    // =============================================================

    event ProfileCreated(string indexed cccd, string name);
    event TreatmentLogAdded(string indexed cccd);
    event FundsDeposited(address indexed from, uint256 amount);
    event EmergencyEventCreated(uint256 indexed eventId, address indexed patientAddress, string patientCccd);
    event RescuerAssigned(uint256 indexed eventId, address indexed rescuerAddress);
    event RescueConfirmed(uint256 indexed eventId, address indexed officialRescuerAddress);
    event PaymentExecuted(uint256 indexed eventId, address indexed officialRescuerAddress, uint256 amount);

    // =============================================================
    // CONSTRUCTOR
    // =============================================================

    // Đặt địa chỉ ví triển khai contract làm Chủ sở hữu (Owner)
    // Địa chỉ này sẽ đại diện cho Hệ thống/Oracle
    constructor() Ownable(msg.sender) {}

    // =============================================================
    // FUNCTIONS (11 HÀM CHỨC NĂNG)
    // =============================================================

    // --- Nhóm 1: Quản lý Hồ sơ ---

    /**
     * @dev Khởi tạo hồ sơ y tế bảo mật bằng CCCD
     */
    function createProfile(
        string memory _cccd,
        string memory _name,
        uint256 _age,
        string memory _allergies,
        string memory _conditions
    ) external {
        // Logic sẽ được thêm vào sau
    }

    /**
     * @dev Thêm một bản ghi lịch sử điều trị vào hồ sơ CCCD
     */
    function addTreatmentLog(
        string memory _cccd,
        string memory _location,
        string memory _verifierName,
        string memory _details // Gộp (Tình trạng, Thuốc, Thiết bị)
    ) external {
        // Logic sẽ được thêm vào sau
        // (Trong demo có thể để public, thực tế nên giới hạn chỉ Provider)
    }

    /**
     * @dev Truy vấn hồ sơ y tế (Ai cũng xem được trong demo)
